import React, { Component } from 'react';
import { Button } from 'reactstrap';
import 'bootstrap/dist/css/bootstrap.min.css';

class App extends Component {
    constructor(props) {
        super(props);
        this.state = {
            colores: ["primary", "secondary", "success", "info", "warning", "danger"],
            nombres: ["azul", "gris", "verde", "azul", "amarillo", "rojo"],
            coloresActuales: Array(6).fill("secondary"),
            nombresActuales: Array(6).fill("press"),
        }
    }

    cambiarContenido(p) {
        let col = Array(6).fill("secondary");
        col[p] = this.state.colores[p];

        let nom = Array(6).fill("press");
        nom[p] = this.state.nombres[p];

        this.setState({ coloresActuales: col, nombresActuales: nom });
    }

    render() {
        return (
            <div className="App">
                <div>
                    <Botoncico pos={0} color={(p) => this.state.coloresActuales[p]} nombre={(p) => this.state.nombresActuales[p]} cambiar={(p) => this.cambiarContenido(p)} />
                    <Botoncico pos={1} color={(p) => this.state.coloresActuales[p]} nombre={(p) => this.state.nombresActuales[p]} cambiar={(p) => this.cambiarContenido(p)} />
                    <Botoncico pos={2} color={(p) => this.state.coloresActuales[p]} nombre={(p) => this.state.nombresActuales[p]} cambiar={(p) => this.cambiarContenido(p)} />
                    <Botoncico pos={3} color={(p) => this.state.coloresActuales[p]} nombre={(p) => this.state.nombresActuales[p]} cambiar={(p) => this.cambiarContenido(p)} />
                    <Botoncico pos={4} color={(p) => this.state.coloresActuales[p]} nombre={(p) => this.state.nombresActuales[p]} cambiar={(p) => this.cambiarContenido(p)} />
                    <Botoncico pos={5} color={(p) => this.state.coloresActuales[p]} nombre={(p) => this.state.nombresActuales[p]} cambiar={(p) => this.cambiarContenido(p)} />
                </div>
            </div>
        );
    }
}

function Botoncico(props) {
    return (
        <Button color={() => props.color(props.pos)} onClick={() => props.cambiar(props.pos)}> {() => props.nombre(props.pos)} </Button>
    );
}

export default App;
